export function EmptyState({ text, icon: Icon = Inbox, children }: { text: string; icon?: React.ComponentType<{ className?: string }>; children?: React.ReactNode }) {
  return (
    <div className="flex flex-col items-center justify-center gap-2 py-10 text-center">
      <div className="pp-float flex h-12 w-12 items-center justify-center rounded-full border bg-muted/60">
        <Icon className="h-5 w-5 text-muted-foreground" />
      </div>
      <p className="text-sm text-muted-foreground">{text}</p>
      {children}
    </div>
  )
}
